#!/usr/bin/env dotnet
// friday13.cs — Friday the 13th in the proleptic Gregorian calendar

// Find the earliest Friday the 13th starting from 0001-01-01
var earliest = Enumerable.Range(1, 12)
    .Select(m => new DateTime(1, m, 13))
    .First(d => d.DayOfWeek == DayOfWeek.Friday);

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest:dddd})");

// Count Friday the 13ths in one full 400-year cycle (years 1–400)
// The Gregorian calendar repeats exactly every 400 years.
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        if (new DateTime(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");

// Bonus: breakdown by month
var byMonth = Enumerable.Range(1, 400)
    .SelectMany(y => Enumerable.Range(1, 12), (y, m) => new DateTime(y, m, 13))
    .Where(d => d.DayOfWeek == DayOfWeek.Friday)
    .GroupBy(d => d.Month)
    .OrderByDescending(g => g.Count())
    .Select(g => $"  {CultureInfo.InvariantCulture.DateTimeFormat.GetMonthName(g.Key),-12} {g.Count()}");

Console.WriteLine("\nBreakdown by month:");
foreach (var line in byMonth)
    Console.WriteLine(line);

